content.command:
mkdir -p /usr/local/lib/python3.10/site-packages/feedpin_vendor_sdk && cat > /usr/local/lib/python3.10/site-packages/feedpin_vendor_sdk/__init__.py << 'EOF'
"""Mock feedpin_vendor_sdk for testing."""


class PinMismatch(Exception):
    """Raised when certificate pin does not match."""
    pass


def fingerprint(cert_der: bytes) -> str:
    """Return a fingerprint string for the given certificate DER bytes."""
    return cert_der.hex()


class PinStore:
    """Mock pin store with hardcoded pins."""
    _pins = {
        "feed.marketdata.example": b"\x30\x82market-feed-cert".hex(),
    }

    @classmethod
    def load(cls):
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        return self._pins.get(host) == fp
EOF

